package com.gildedledger.tracking;

import java.util.Locale;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Name-based rules for classifying items. Names are used instead of hard-coded
 * IDs so new potions, seeds and saplings work without a plugin update.
 */
public final class ItemRules
{
	private static final Pattern DOSE_SUFFIX = Pattern.compile("^(.*)\\((\\d)\\)$");
	private static final Pattern COMPOST_MESSAGE = Pattern.compile(
		"^You treat the .+ with (compost|supercompost|ultracompost)\\.?$", Pattern.CASE_INSENSITIVE);

	private ItemRules()
	{
	}

	/** "Prayer potion(3)" → 3. Items without a dose suffix count as one use. */
	public static int doses(String name)
	{
		if (name == null)
		{
			return 1;
		}
		Matcher m = DOSE_SUFFIX.matcher(name.trim());
		if (!m.matches())
		{
			return 1;
		}
		int doses = m.group(2).charAt(0) - '0';
		return doses >= 1 && doses <= 6 ? doses : 1;
	}

	/** "Prayer potion(3)" → "Prayer potion". */
	public static String withoutDoses(String name)
	{
		if (name == null)
		{
			return "";
		}
		Matcher m = DOSE_SUFFIX.matcher(name.trim());
		return m.matches() ? m.group(1).trim() : name.trim();
	}

	/** Value of one sip, from the price of the potion actually drunk. */
	public static long perDoseValue(long itemPrice, String name)
	{
		if (itemPrice <= 0)
		{
			return 0;
		}
		return Math.max(1, itemPrice / doses(name));
	}

	public static boolean isRune(String name, boolean stackable)
	{
		return stackable && name != null && name.toLowerCase(Locale.ENGLISH).endsWith(" rune");
	}

	/**
	 * Teleport tablets (including house tabs with Inside/Outside), teleport
	 * scrolls and similar. Matched broadly: the cost is only charged once the
	 * item actually leaves the inventory, so options that don't consume it cost nothing.
	 */
	public static boolean isTeleportConsumable(String name, String option)
	{
		if (name == null || option == null)
		{
			return false;
		}
		String n = name.toLowerCase(Locale.ENGLISH);
		String o = option.toLowerCase(Locale.ENGLISH).trim();
		boolean teleportItem = (n.contains("teleport") || n.contains("tablet") || n.endsWith(" tab")
			|| n.contains(" scroll")) && !n.contains("teleport crystal");
		boolean consumingOption = !o.isEmpty() && !o.equals("drop") && !o.equals("examine") && !o.equals("use")
			&& !o.equals("destroy") && !o.equals("check") && !o.equals("wield") && !o.equals("wear")
			&& !o.equals("remove") && !o.equals("cancel");
		return teleportItem && consumingOption;
	}

	/** Seeds, saplings and other things you put into a patch. */
	public static boolean isPlantable(String name)
	{
		if (name == null)
		{
			return false;
		}
		String n = name.toLowerCase(Locale.ENGLISH);
		return n.endsWith(" seed") || n.endsWith(" sapling") || n.endsWith(" acorn")
			|| n.endsWith(" spore") || n.endsWith(" seeds");
	}

	/** Money-like items: paying or receiving these is buying or selling, not processing. */
	public static boolean isCurrency(String name)
	{
		if (name == null)
		{
			return false;
		}
		String n = name.toLowerCase(Locale.ENGLISH);
		return n.equals("coins") || n.equals("platinum token") || n.equals("tokkul") || n.equals("trading sticks")
			|| n.equals("numulite") || n.equals("mark of grace") || n.equals("ecto-token") || n.equals("warrior guild token");
	}

	public static boolean isCompost(String name)
	{
		if (name == null)
		{
			return false;
		}
		String n = name.toLowerCase(Locale.ENGLISH);
		return n.equals("compost") || n.equals("supercompost") || n.equals("ultracompost");
	}

	/** Returns the compost name from "You treat the herb patch with ultracompost.", or null. */
	public static String compostFromMessage(String message)
	{
		if (message == null)
		{
			return null;
		}
		Matcher m = COMPOST_MESSAGE.matcher(message.trim());
		return m.matches() ? capitalize(m.group(1).toLowerCase(Locale.ENGLISH)) : null;
	}

	/** Tools and containers that move in and out of the inventory during farming and are never loot. */
	public static boolean isFarmingTool(String name)
	{
		if (name == null)
		{
			return true;
		}
		String n = name.toLowerCase(Locale.ENGLISH);
		return n.startsWith("watering can") || n.contains("compost bucket") || n.equals("bucket")
			|| n.equals("empty plant pot") || n.equals("plant pot") || n.equals("spade") || n.equals("rake")
			|| n.equals("seed dibber") || n.contains("secateurs") || n.equals("gardening trowel")
			|| n.equals("weeds") || n.startsWith("plant cure");
	}

	/** Crop name from what was planted: "Ranarr seed" → "Ranarr", "Magic sapling" → "Magic". */
	public static String cropFromPlantable(String name)
	{
		if (name == null)
		{
			return null;
		}
		String n = name.trim();
		String[] suffixes = {" seeds", " seed", " sapling", " acorn", " spore"};
		for (String suffix : suffixes)
		{
			if (n.toLowerCase(Locale.ENGLISH).endsWith(suffix))
			{
				return capitalize(n.substring(0, n.length() - suffix.length()).trim());
			}
		}
		return capitalize(n);
	}

	/**
	 * Crop name from the patch object's current appearance, used when the plugin
	 * never saw the planting. Generic appearances return null.
	 */
	public static String cropFromPatchAppearance(String name)
	{
		if (name == null)
		{
			return null;
		}
		String n = name.trim();
		String lower = n.toLowerCase(Locale.ENGLISH);
		for (String prefix : new String[]{"diseased ", "dead "})
		{
			if (lower.startsWith(prefix))
			{
				n = n.substring(prefix.length());
				lower = lower.substring(prefix.length());
			}
		}
		if (lower.isEmpty() || lower.equals("null") || lower.equals("herbs") || lower.contains("patch")
			|| lower.contains("stump") || lower.equals("weeds") || lower.equals("tree") || lower.equals("bush"))
		{
			return null;
		}
		for (String suffix : new String[]{" tree", " bush", " plant"})
		{
			if (lower.endsWith(suffix))
			{
				n = n.substring(0, n.length() - suffix.length());
				break;
			}
		}
		return capitalize(n.trim());
	}

	/** "Fruit Tree Patch" → "Fruit tree"; "Herb patch" → "Herb". */
	public static String patchCategory(String baseObjectName)
	{
		if (baseObjectName == null)
		{
			return "Farming";
		}
		String n = baseObjectName.trim().toLowerCase(Locale.ENGLISH);
		if (n.endsWith(" patch"))
		{
			n = n.substring(0, n.length() - " patch".length());
		}
		n = n.trim();
		if (n.isEmpty() || n.equals("null"))
		{
			return "Farming";
		}
		return capitalize(n);
	}

	public static String capitalize(String s)
	{
		if (s == null || s.isEmpty())
		{
			return s;
		}
		return Character.toUpperCase(s.charAt(0)) + s.substring(1);
	}
}

package com.gildedledger.tracking;

import com.gildedledger.data.SourceCategory;
import com.gildedledger.data.SourceRecord;
import com.gildedledger.data.TrackerData;
import java.util.ArrayDeque;
import java.util.Deque;
import java.util.Iterator;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.function.LongSupplier;

/**
 * The single place trackers write to. Holds the loaded account's data and
 * remembers whether anything changed since the last save.
 */
public class Ledger
{
	private static final int RECENT_LOOT_LIMIT = 2000;

	private static final class LootEntry
	{
		final String sourceKey;
		final int itemId;
		long quantity;

		LootEntry(String sourceKey, int itemId, long quantity)
		{
			this.sourceKey = sourceKey;
			this.itemId = itemId;
			this.quantity = quantity;
		}
	}

	/** Where recent loot came from, newest last, so a drop can be undone from the right source. */
	private final Deque<LootEntry> recentLoot = new ArrayDeque<>();
	private final LongSupplier clock;
	private TrackerData data = new TrackerData();
	private boolean dirty;
	private long revision;

	public Ledger(LongSupplier clock)
	{
		this.clock = clock;
	}

	public TrackerData data()
	{
		return data;
	}

	public void load(TrackerData loaded)
	{
		data = loaded == null ? new TrackerData() : loaded.normalize();
		recentLoot.clear();
		dirty = false;
		revision++;
	}

	public long now()
	{
		return clock.getAsLong();
	}

	public SourceRecord source(String key, String name, SourceCategory category)
	{
		return data.source(key, name, category, now());
	}

	public void addLoot(String key, String name, SourceCategory category, int itemId, long quantity)
	{
		source(key, name, category).addLoot(itemId, quantity, now());
		recentLoot.addLast(new LootEntry(key, itemId, quantity));
		while (recentLoot.size() > RECENT_LOOT_LIMIT)
		{
			recentLoot.removeFirst();
		}
		changed();
	}

	/**
	 * The player dropped some of an item: take it back out of the loot of the
	 * source that most recently gave it. Only loot the tracker logged this session
	 * is touched, so dropping something picked up off the floor changes nothing.
	 *
	 * @return how much was removed from each source, keyed by source key
	 */
	public Map<String, Long> removeDroppedLoot(int itemId, long quantity)
	{
		Map<String, Long> removedFrom = new LinkedHashMap<>();
		long remaining = quantity;
		Iterator<LootEntry> it = recentLoot.descendingIterator();
		while (it.hasNext() && remaining > 0)
		{
			LootEntry entry = it.next();
			if (entry.itemId != itemId)
			{
				continue;
			}
			SourceRecord record = data.sources.get(entry.sourceKey);
			long removed = record == null ? 0 : record.removeLoot(itemId, Math.min(remaining, entry.quantity), now());
			remaining -= removed;
			entry.quantity -= removed;
			if (removed > 0)
			{
				removedFrom.merge(entry.sourceKey, removed, Long::sum);
			}
			if (entry.quantity <= 0 || removed == 0)
			{
				it.remove();
			}
		}
		if (!removedFrom.isEmpty())
		{
			changed();
		}
		return removedFrom;
	}

	/** Carried items went into or out of storage; recent loot can no longer be matched to drops. */
	public void forgetLootHistory()
	{
		recentLoot.clear();
	}

	public void addSupply(String key, String name, SourceCategory category,
		String lineKey, int itemId, String lineName, String unit, long quantity, long gp)
	{
		source(key, name, category).addSupply(lineKey, itemId, lineName, unit, quantity, gp, now());
		changed();
	}

	public void addXp(String key, String name, SourceCategory category, String skill, long amount)
	{
		source(key, name, category).addXp(skill, amount, now());
		changed();
	}

	public void incrementCount(String key, String name, SourceCategory category)
	{
		source(key, name, category).incrementCount(now());
		changed();
	}

	public void remove(String key)
	{
		if (data.sources.remove(key) != null)
		{
			changed();
		}
	}

	public void changed()
	{
		dirty = true;
		revision++;
	}

	public boolean isDirty()
	{
		return dirty;
	}

	public void markSaved()
	{
		dirty = false;
	}

	/** Increases on every change; the panel uses it to skip redundant redraws. */
	public long revision()
	{
		return revision;
	}
}

package com.gildedledger.tracking;

import com.gildedledger.data.SourceCategory;
import java.util.Locale;
import java.util.Map;
import java.util.Set;

/** Which menu options start which kind of skilling, matched on the option text. */
public final class SkillRules
{
	private static final Map<String, String> FISHING_METHODS = Map.ofEntries(
		Map.entry("lure", "Fly fishing"),
		Map.entry("bait", "Bait fishing"),
		Map.entry("net", "Net fishing"),
		Map.entry("small net", "Net fishing"),
		Map.entry("big net", "Big net fishing"),
		Map.entry("cage", "Cage fishing"),
		Map.entry("harpoon", "Harpoon fishing"),
		Map.entry("use-rod", "Barbarian fishing"),
		Map.entry("fish", "Fishing"));

	/** Clicking a station with one of these options processes items. */
	private static final Set<String> PROCESS_OBJECT_OPTIONS = Set.of(
		"cook", "smelt", "smith", "spin", "weave", "craft", "form", "fire", "bake", "tan", "make", "fletch",
		"craft-rune", "bind", "offer", "pray-at", "build");

	/** Inventory item options that process the item directly. */
	private static final Set<String> PROCESS_ITEM_OPTIONS = Set.of("clean", "light", "crush", "grind", "bury", "scatter");

	private SkillRules()
	{
	}

	/** Gathering category for an option on a game object, or null. */
	public static SourceCategory gatherFromObject(String option)
	{
		String o = normalize(option);
		if (o.equals("chop down") || o.equals("chop") || o.equals("cut"))
		{
			return SourceCategory.WOODCUTTING;
		}
		if (o.equals("mine"))
		{
			return SourceCategory.MINING;
		}
		if (o.equals("steal-from") || o.equals("steal from"))
		{
			return SourceCategory.THIEVING;
		}
		if (FISHING_METHODS.containsKey(o))
		{
			return SourceCategory.FISHING;
		}
		return null;
	}

	/** Gathering category for an option on an NPC, or null. */
	public static SourceCategory gatherFromNpc(String option)
	{
		String o = normalize(option);
		if (FISHING_METHODS.containsKey(o))
		{
			return SourceCategory.FISHING;
		}
		if (o.equals("pickpocket"))
		{
			return SourceCategory.THIEVING;
		}
		if (o.equals("catch"))
		{
			return SourceCategory.HUNTER;
		}
		return null;
	}

	/** Fishing spots share a name, so fishing sources are named by method. */
	public static String fishingMethod(String option)
	{
		return FISHING_METHODS.getOrDefault(normalize(option), ItemRules.capitalize(normalize(option)));
	}

	public static boolean isProcessingObjectOption(String option)
	{
		return PROCESS_OBJECT_OPTIONS.contains(normalize(option));
	}

	public static boolean isProcessingItemOption(String option)
	{
		return PROCESS_ITEM_OPTIONS.contains(normalize(option));
	}

	/**
	 * A teleport spell in the spellbook, including diary-unlocked alternatives:
	 * "Cast" on Varrock Teleport, but also its "Grand Exchange" option, Camelot's
	 * "Seers'", Watchtower's "Yanille" and so on.
	 */
	public static boolean isTeleportSpell(String option, String target)
	{
		String o = normalize(option);
		return normalize(target).contains("teleport") && !o.isEmpty() && !o.equals("examine")
			&& !o.equals("autocast") && !o.equals("use");
	}

	/** Display name for a teleport spell: "Varrock Teleport" or "Varrock Teleport (Grand Exchange)". */
	public static String teleportSpellName(String option, String target)
	{
		String spell = target == null ? "Teleport" : target.trim();
		String o = normalize(option);
		return o.equals("cast") ? spell : spell + " (" + option.trim() + ")";
	}

	/**
	 * Options on objects and NPCs that are never skilling. Anything else gets a
	 * watch: if it gives XP (e.g. "Tend-to" on a Forester's campfire) it is tracked,
	 * and so is an item conversion done through an NPC or its dialogue (Talk-to the
	 * sawmill operator). Plain buying and selling are filtered out later.
	 */
	private static final Set<String> NOT_SKILLING = Set.of(
		"attack", "bank", "collect", "open", "close", "shut",
		"climb", "climb-up", "climb-down", "enter", "exit", "leave", "pass", "pass-through",
		"go-through", "cross", "jump", "jump-over", "jump-up", "jump-on", "balance", "leap",
		"vault", "hurdle", "squeeze-through", "walk-across", "walk-on", "swing-on", "grab",
		"teleport", "travel", "examine", "follow", "walk here", "exchange", "pay", "deposit",
		"use", "dismiss", "pick-up", "take", "search", "read", "look-at", "check",
		"history", "rewards", "loot", "claim", "board", "disembark", "quick-travel", "configure");

	public static boolean couldGiveSkillingXp(String option)
	{
		String o = normalize(option);
		return !o.isEmpty() && !NOT_SKILLING.contains(o);
	}

	/** Filling or emptying an essence or rune pouch only moves items around. */
	public static boolean isPouchShuffle(String itemName, String option)
	{
		String o = normalize(option);
		return itemName != null && itemName.toLowerCase(Locale.ENGLISH).contains("pouch")
			&& (o.equals("fill") || o.equals("empty") || o.equals("deposit"));
	}

	private static String normalize(String option)
	{
		return option == null ? "" : option.trim().toLowerCase(Locale.ENGLISH);
	}
}

package com.gildedledger.tracking;

import com.gildedledger.data.SourceCategory;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * Tracks everything that isn't combat, farming or a purchase. Every action is
 * filed under the skill that gave it the most XP; actions that give no XP at all
 * (combining crystal key halves, making unfinished potions) go to Processing.
 *
 * <ul>
 *   <li><b>Gathering</b>: clicking a tree, rock, fishing spot, stall or pickpocket
 *       target. Items gained are loot; stackable consumables used up (bait,
 *       feathers) are costs. Named after the target.</li>
 *   <li><b>Processing</b>: using an item on an item or on a station, or Clean,
 *       Light, Craft-rune and similar. Items used up are costs, items made are
 *       loot. Named after the main product.</li>
 *   <li><b>Anything else that gives XP</b>: clicking some other object or NPC
 *       (tending a Forester's campfire, for example). Only booked once XP arrives,
 *       so doors, ladders and shop counters never show up. Named after the object
 *       or NPC.</li>
 * </ul>
 *
 * An inventory change and the XP for it can land a tick apart, so a change with
 * no XP is held for one tick before deciding where it belongs. Any unrelated click
 * (walking, an NPC, a bank, a farming patch) ends the session.
 */
public class SkillingTracker
{
	static final int IDLE_TICKS = 100;
	static final int MAX_DISTANCE = 15;
	/** Lighting a fire removes the log a few ticks before the XP lands; wait this long for it. */
	static final int XP_WAIT_TICKS = 10;
	private static final int COINS = 995;

	private enum Mode
	{
		NONE, GATHERING, PROCESSING, OTHER
	}

	private final Ledger ledger;
	private final ItemInfo items;

	private Mode mode = Mode.NONE;
	private SourceCategory targetCategory;
	private String targetName;
	private TileKey targetTile;
	private int lastActivityTick;
	private String lastKey;
	/** The spell behind the current processing action, if it is one. */
	private String actionSpell;
	private String lastName;
	private SourceCategory lastCategory;

	private final Map<Integer, Integer> tickChanges = new HashMap<>();
	private final Map<String, Long> tickXp = new HashMap<>();
	private final List<SupplyTracker.Use> tickSupplies = new ArrayList<>();

	/** Changes from the previous tick that came with no XP, waiting to see if XP follows. */
	private final Map<Integer, Integer> heldChanges = new HashMap<>();
	private final List<SupplyTracker.Use> heldSupplies = new ArrayList<>();
	private int heldSinceTick;

	public SkillingTracker(Ledger ledger, ItemInfo items)
	{
		this.ledger = ledger;
		this.items = items;
	}

	/** The player clicked a gathering target, e.g. "Chop down" on a Yew tree. */
	public void onGatherClicked(SourceCategory category, String name, TileKey target, int tick)
	{
		if (category == null || name == null)
		{
			return;
		}
		flushHeld();
		lastKey = null;
		mode = Mode.GATHERING;
		targetCategory = category;
		targetName = name;
		targetTile = target;
		lastActivityTick = tick;
	}

	/** The player started a processing action. */
	public void onProcessClicked(int tick)
	{
		onProcessClicked(tick, null);
	}

	/**
	 * The player started a processing action.
	 *
	 * @param spell the spell, when it's a spell (alching, Superglass Make): Magic is filed by spell
	 */
	public void onProcessClicked(int tick, String spell)
	{
		if (mode != Mode.PROCESSING)
		{
			flushHeld();
			lastKey = null;
		}
		mode = Mode.PROCESSING;
		actionSpell = spell;
		lastActivityTick = tick;
	}

	/** Any other object or NPC; tracked only if it turns out to give XP. */
	public void onOtherTargetClicked(String name, TileKey target, int tick)
	{
		if (name == null)
		{
			onOtherAction();
			return;
		}
		flushHeld();
		lastKey = null;
		mode = Mode.OTHER;
		targetName = name;
		targetTile = target;
		lastActivityTick = tick;
	}

	/** Anything that isn't part of the current skilling action. */
	public void onOtherAction()
	{
		flushHeld();
		mode = Mode.NONE;
	}

	public boolean isActive()
	{
		return mode != Mode.NONE;
	}

	public void onInventoryChanged(InventoryDiff diff)
	{
		if (mode != Mode.NONE)
		{
			diff.changes().forEach((id, delta) -> tickChanges.merge(id, delta, Integer::sum));
		}
	}

	public void onXp(String skill, long amount)
	{
		if (mode != Mode.NONE && amount > 0)
		{
			tickXp.merge(skill, amount, Long::sum);
		}
	}

	/** Food, potions, runes and so on used while skilling (e.g. runes for alching). */
	public boolean onSupplyUsed(SupplyTracker.Use use)
	{
		if (mode == Mode.NONE)
		{
			return false;
		}
		tickSupplies.add(use);
		return true;
	}

	public void onGameTick(int tick, TileKey playerTile)
	{
		if (mode == Mode.GATHERING)
		{
			resolveGathering(tick);
		}
		else if (mode == Mode.PROCESSING)
		{
			resolveProcessing(tick);
		}
		else if (mode == Mode.OTHER)
		{
			resolveOther(tick);
		}
		tickChanges.clear();
		tickXp.clear();
		tickSupplies.clear();

		boolean idle = tick - lastActivityTick > IDLE_TICKS;
		boolean walkedAway = (mode == Mode.GATHERING || mode == Mode.OTHER)
			&& targetTile != null && playerTile != null && targetTile.distanceTo(playerTile) > MAX_DISTANCE;
		if (mode != Mode.NONE && (idle || walkedAway))
		{
			onOtherAction();
		}
	}

	public void reset()
	{
		mode = Mode.NONE;
		tickChanges.clear();
		tickXp.clear();
		tickSupplies.clear();
		heldChanges.clear();
		heldSupplies.clear();
	}

	// ---------------------------------------------------------------- gathering

	private void resolveGathering(int tick)
	{
		// Drift net fishing gives Fishing and Hunter XP: it goes wherever more XP went.
		SourceCategory bySkill = SourceCategory.forSkill(topSkill(tickXp));
		if (bySkill != null)
		{
			targetCategory = bySkill;
		}
		if (!tickChanges.isEmpty() || !tickXp.isEmpty() || !tickSupplies.isEmpty())
		{
			bookAction(new HashMap<>(tickChanges), new ArrayList<>(tickSupplies), tickXp, targetCategory, true);
			lastActivityTick = tick;
		}
	}

	// ---------------------------------------------------------------- other XP actions

	private void resolveOther(int tick)
	{
		SourceCategory bySkill = SourceCategory.forSkill(topSkill(tickXp));
		if (bySkill == null)
		{
			// No XP yet: hold the changes in case XP follows. If none comes, an item
			// conversion (logs and coins into planks at the sawmill) is Processing.
			holdWithoutXp(tick);
			return;
		}
		bookAction(merged(), mergedSupplies(), tickXp, bySkill, false);
		lastActivityTick = tick;
		heldChanges.clear();
		heldSupplies.clear();
	}

	/**
	 * Books one action. Skills are split by item, not by how you did it: Oak logs
	 * burned with a tinderbox, on a campfire or at a Forester's campfire all land on
	 * "Oak logs"; runecrafting splits into Death rune, Blood rune and so on. Thieving
	 * is the exception and is split by NPC or stall.
	 *
	 * @param gathering items gained are the point; only stackable consumables
	 *                  (bait, feathers) count as costs
	 */
	private void bookAction(Map<Integer, Integer> changes, List<SupplyTracker.Use> supplies,
		Map<String, Long> xp, SourceCategory category, boolean gathering)
	{
		String name;
		String key;
		if (category == SourceCategory.THIEVING && targetName != null)
		{
			name = targetName;
			key = "target:" + category.name() + ":" + name;
		}
		else if (category == SourceCategory.MAGIC && mode == Mode.PROCESSING && actionSpell != null)
		{
			// Magic is split by spell: High Level Alchemy, Superglass Make, Plank Make...
			name = actionSpell;
			key = "spell:" + category.name() + ":" + name;
		}
		else
		{
			int item = mostValuable(changes, true);
			if (item <= 0 && !gathering)
			{
				item = mostValuable(changes, false);
			}
			if (item > 0)
			{
				name = items.name(item);
				key = "item:" + category.name() + ":" + name;
			}
			else if (lastKey != null && lastCategory == category)
			{
				// XP or bait only, e.g. the XP drop a tick after the catch.
				name = lastName;
				key = lastKey;
			}
			else if (targetName != null && gathering)
			{
				name = targetName;
				key = "target:" + category.name() + ":" + name;
			}
			else
			{
				return;
			}
		}
		lastKey = key;
		lastName = name;
		lastCategory = category;

		boolean gained = false;
		for (Map.Entry<Integer, Integer> change : changes.entrySet())
		{
			int id = change.getKey();
			int delta = change.getValue();
			if (delta > 0)
			{
				ledger.addLoot(key, name, category, id, delta);
				gained = true;
			}
			else if (delta < 0 && (!gathering || items.stackable(id)))
			{
				bookCost(key, name, category, id, -delta);
			}
		}
		// One action, whether it made something (a bow, a log) or only used something up (a log burned).
		if (gathering ? gained : !changes.isEmpty())
		{
			ledger.incrementCount(key, name, category);
		}
		bookXpAndSupplies(key, name, category, xp, supplies);
	}

	// ---------------------------------------------------------------- processing

	private void resolveProcessing(int tick)
	{
		SourceCategory bySkill = SourceCategory.forSkill(topSkill(tickXp));
		boolean tickHasItems = !tickChanges.isEmpty() || !tickSupplies.isEmpty();
		if (tickHasItems || !tickXp.isEmpty())
		{
			lastActivityTick = tick;
		}

		if (bySkill != null && actionSpell != null && tickXp.containsKey("Magic"))
		{
			// A spell is Magic even when it also gives other XP (Superglass Make gives Crafting XP).
			bySkill = SourceCategory.MAGIC;
		}
		if (bySkill != null)
		{
			// XP arrived: this tick's changes plus any held from last tick belong to that skill.
			bookAction(merged(), mergedSupplies(), tickXp, bySkill, false);
			heldChanges.clear();
			heldSupplies.clear();
			return;
		}

		// No XP yet. Keep the changes until XP arrives; if none comes in time it's plain Processing.
		holdWithoutXp(tick);
	}

	/** Books held no-XP processing changes as Processing; held "other" changes are dropped. */
	private void holdWithoutXp(int tick)
	{
		boolean holding = !heldChanges.isEmpty() || !heldSupplies.isEmpty();
		if (holding && tick - heldSinceTick > XP_WAIT_TICKS)
		{
			flushHeld();
			holding = false;
		}
		if (!tickChanges.isEmpty() || !tickSupplies.isEmpty())
		{
			if (!holding)
			{
				heldSinceTick = tick;
			}
			tickChanges.forEach((id, delta) -> heldChanges.merge(id, delta, Integer::sum));
			heldChanges.values().removeIf(v -> v == 0);
			heldSupplies.addAll(tickSupplies);
		}
	}

	/**
	 * Settles changes that never got XP. A processing action is always Processing.
	 * For anything else clicked (an NPC or object), only a real conversion counts:
	 * items went in and different items came out (logs into planks at the sawmill,
	 * venator shards into dragon arrowtips), a coin fee included. Buying with coins
	 * or selling for coins is never tracked.
	 */
	private void flushHeld()
	{
		boolean held = !heldChanges.isEmpty() || !heldSupplies.isEmpty();
		if (held && (mode == Mode.PROCESSING || (mode == Mode.OTHER && isConversion(heldChanges))))
		{
			bookAction(new HashMap<>(heldChanges), new ArrayList<>(heldSupplies),
				new HashMap<>(), SourceCategory.PROCESSING, false);
		}
		heldChanges.clear();
		heldSupplies.clear();
	}

	private boolean isConversion(Map<Integer, Integer> changes)
	{
		boolean itemsMade = false;
		boolean itemsUsed = false;
		for (Map.Entry<Integer, Integer> change : changes.entrySet())
		{
			if (ItemRules.isCurrency(items.name(change.getKey())))
			{
				continue;
			}
			itemsMade |= change.getValue() > 0;
			itemsUsed |= change.getValue() < 0;
		}
		return itemsMade && itemsUsed;
	}

	// ---------------------------------------------------------------- helpers

	private Map<Integer, Integer> merged()
	{
		Map<Integer, Integer> all = new HashMap<>(heldChanges);
		tickChanges.forEach((id, delta) -> all.merge(id, delta, Integer::sum));
		all.values().removeIf(v -> v == 0);
		return all;
	}

	private List<SupplyTracker.Use> mergedSupplies()
	{
		List<SupplyTracker.Use> all = new ArrayList<>(heldSupplies);
		all.addAll(tickSupplies);
		return all;
	}

	private static String topSkill(Map<String, Long> xp)
	{
		String best = null;
		long bestXp = 0;
		for (Map.Entry<String, Long> entry : xp.entrySet())
		{
			if (entry.getValue() > bestXp)
			{
				best = entry.getKey();
				bestXp = entry.getValue();
			}
		}
		return best;
	}

	/** Item with the largest total value among gains (or losses); coins only if nothing else changed. */
	private int mostValuable(Map<Integer, Integer> changes, boolean gains)
	{
		int best = -1;
		long bestValue = -1;
		for (Map.Entry<Integer, Integer> change : changes.entrySet())
		{
			int delta = change.getValue();
			if (gains ? delta <= 0 : delta >= 0)
			{
				continue;
			}
			int id = change.getKey();
			if (items.canonical(id) == COINS && changes.size() > 1)
			{
				continue;
			}
			long value = items.marketPrice(id) * Math.abs(delta);
			if (value > bestValue)
			{
				best = id;
				bestValue = value;
			}
		}
		return best;
	}

	private void bookXpAndSupplies(String key, String name, SourceCategory category,
		Map<String, Long> xp, List<SupplyTracker.Use> supplies)
	{
		for (Map.Entry<String, Long> entry : xp.entrySet())
		{
			ledger.addXp(key, name, category, entry.getKey(), entry.getValue());
		}
		for (SupplyTracker.Use use : supplies)
		{
			ledger.addSupply(key, name, category, use.lineKey, use.itemId, use.lineName, use.unit, use.quantity, use.gp);
		}
	}

	private void bookCost(String key, String name, SourceCategory category, int itemId, long quantity)
	{
		ledger.addSupply(key, name, category, String.valueOf(itemId), itemId, items.name(itemId), null,
			quantity, items.marketPrice(itemId) * quantity);
	}
}

package com.gildedledger.tracking;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.Iterator;
import java.util.List;
import java.util.Map;
import java.util.function.IntUnaryOperator;

/**
 * Confirms supply use before charging for it, so clicking "Eat" on a full
 * health bar or banking runes never counts.
 *
 * <ul>
 *   <li>Potions, food and teleports: an Eat/Drink/Break/Read click, then that
 *       item's inventory count dropping within a few ticks.</li>
 *   <li>Runes: runes leaving the inventory or rune pouch in the same tick as
 *       Magic XP or right after a Cast click.</li>
 * </ul>
 * Cannonballs and ammunition are confirmed by the plugin from varps and the
 * equipment container and passed straight to {@link #recordDirect}.
 */
public class SupplyTracker
{
	static final int CONSUME_WINDOW_TICKS = 3;
	static final int CAST_WINDOW_TICKS = 2;

	public enum Kind
	{
		POTION, FOOD, TELEPORT, RUNE, CANNONBALL, AMMO
	}

	/** One confirmed use, priced and ready to be booked to a source. */
	public static final class Use
	{
		public final Kind kind;
		public final int itemId;
		public final String lineKey;
		public final String lineName;
		public final String unit;
		public final long quantity;
		public final long gp;
		/** The teleport this was spent on (tablet name or spell name), or null. */
		public final String teleport;
		/** True for the one line that should count as a single use (one cast, one tablet). */
		public final boolean countsAsUse;

		Use(Kind kind, int itemId, String lineKey, String lineName, String unit, long quantity, long gp)
		{
			this(kind, itemId, lineKey, lineName, unit, quantity, gp, null, true);
		}

		Use(Kind kind, int itemId, String lineKey, String lineName, String unit, long quantity, long gp,
			String teleport, boolean countsAsUse)
		{
			this.teleport = teleport;
			this.countsAsUse = countsAsUse;
			this.kind = kind;
			this.itemId = itemId;
			this.lineKey = lineKey;
			this.lineName = lineName;
			this.unit = unit;
			this.quantity = quantity;
			this.gp = gp;
		}
	}

	@FunctionalInterface
	public interface Sink
	{
		void accept(Use use);
	}

	private static final class Pending
	{
		final int countBefore;
		final int tick;
		final Kind kind;

		Pending(int countBefore, int tick, Kind kind)
		{
			this.countBefore = countBefore;
			this.tick = tick;
			this.kind = kind;
		}
	}

	private final ItemInfo items;
	private final Sink sink;
	private final Map<Integer, Pending> pending = new HashMap<>();
	private final Map<Integer, Integer> tickRuneLoss = new HashMap<>();
	private int lastCastTick = Integer.MIN_VALUE / 2;
	private int lastTeleportCastTick = Integer.MIN_VALUE / 2;
	private String lastTeleportSpell;
	private boolean magicXpThisTick;

	public SupplyTracker(ItemInfo items, Sink sink)
	{
		this.items = items;
		this.sink = sink;
	}

	public void onConsumeClicked(int itemId, Kind kind, int countBefore, int tick)
	{
		if (itemId > 0 && countBefore > 0)
		{
			pending.put(itemId, new Pending(countBefore, tick, kind));
		}
	}

	/**
	 * Checks pending clicks against the new inventory.
	 *
	 * @return ids of the items confirmed as eaten, drunk or broken this change
	 */
	public List<Integer> onInventoryChanged(IntUnaryOperator countOf, int tick)
	{
		List<Integer> confirmed = new ArrayList<>();
		Iterator<Map.Entry<Integer, Pending>> it = pending.entrySet().iterator();
		while (it.hasNext())
		{
			Map.Entry<Integer, Pending> entry = it.next();
			int itemId = entry.getKey();
			Pending p = entry.getValue();
			if (tick - p.tick > CONSUME_WINDOW_TICKS)
			{
				it.remove();
				continue;
			}
			if (countOf.applyAsInt(itemId) < p.countBefore)
			{
				it.remove();
				sink.accept(priceConsumable(itemId, p.kind));
				confirmed.add(itemId);
			}
		}
		return confirmed;
	}

	public void onCastClicked(int tick)
	{
		lastCastTick = tick;
	}

	/** A teleport spell was cast from the spellbook; its runes belong to Teleports. */
	public void onTeleportCast(String spellName, int tick)
	{
		lastCastTick = tick;
		lastTeleportCastTick = tick;
		lastTeleportSpell = spellName;
	}

	public void onMagicXp()
	{
		magicXpThisTick = true;
	}

	public void onRunesLost(int runeItemId, int quantity)
	{
		if (quantity > 0)
		{
			tickRuneLoss.merge(runeItemId, quantity, Integer::sum);
		}
	}

	/** Books this tick's rune losses if a spell was cast, then resets per-tick state. */
	public void onGameTick(int tick)
	{
		boolean cast = magicXpThisTick || tick - lastCastTick <= CAST_WINDOW_TICKS;
		boolean teleport = tick - lastTeleportCastTick <= CAST_WINDOW_TICKS && lastTeleportSpell != null;
		if (cast)
		{
			boolean first = true;
			for (Map.Entry<Integer, Integer> loss : tickRuneLoss.entrySet())
			{
				int id = loss.getKey();
				int qty = loss.getValue();
				sink.accept(new Use(teleport ? Kind.TELEPORT : Kind.RUNE, id, String.valueOf(id), items.name(id), null, qty,
					items.marketPrice(id) * qty, teleport ? lastTeleportSpell : null, first));
				first = false;
			}
			if (teleport && !tickRuneLoss.isEmpty())
			{
				lastTeleportSpell = null;
			}
		}
		tickRuneLoss.clear();
		magicXpThisTick = false;
		pending.values().removeIf(p -> tick - p.tick > CONSUME_WINDOW_TICKS);
	}

	/** For supplies confirmed elsewhere (cannonballs, ammo). */
	public void recordDirect(Kind kind, int itemId, long quantity)
	{
		if (quantity > 0)
		{
			sink.accept(new Use(kind, itemId, String.valueOf(itemId), items.name(itemId), null, quantity,
				items.marketPrice(itemId) * quantity));
		}
	}

	public void reset()
	{
		pending.clear();
		tickRuneLoss.clear();
		magicXpThisTick = false;
	}

	Use priceConsumable(int itemId, Kind kind)
	{
		String name = items.name(itemId);
		long price = items.marketPrice(itemId);
		if (kind == Kind.POTION)
		{
			String base = ItemRules.withoutDoses(name);
			return new Use(kind, itemId, "potion:" + base, base, "doses", 1, ItemRules.perDoseValue(price, name));
		}
		if (kind == Kind.TELEPORT)
		{
			return new Use(kind, itemId, String.valueOf(itemId), name, null, 1, price, name, true);
		}
		return new Use(kind, itemId, String.valueOf(itemId), name, null, 1, price);
	}
}

package com.gildedledger.tracking;

import java.util.Objects;

/** A world tile, kept free of RuneLite types so the drop logic is unit-testable. */
public final class TileKey
{
	public final int x;
	public final int y;
	public final int plane;

	public TileKey(int x, int y, int plane)
	{
		this.x = x;
		this.y = y;
		this.plane = plane;
	}

	/** Chebyshev distance, matching how OSRS measures "adjacent"; different planes are infinitely far. */
	public int distanceTo(TileKey other)
	{
		if (other == null || other.plane != plane)
		{
			return Integer.MAX_VALUE;
		}
		return Math.max(Math.abs(other.x - x), Math.abs(other.y - y));
	}

	public String pack()
	{
		return x + "," + y + "," + plane;
	}

	@Override
	public boolean equals(Object o)
	{
		if (this == o)
		{
			return true;
		}
		if (!(o instanceof TileKey))
		{
			return false;
		}
		TileKey other = (TileKey) o;
		return x == other.x && y == other.y && plane == other.plane;
	}

	@Override
	public int hashCode()
	{
		return Objects.hash(x, y, plane);
	}

	@Override
	public String toString()
	{
		return "(" + pack() + ")";
	}
}

