	private JPanel lootGrid(String sourceKey, List<PanelModel.LootView> items)
	{
		JPanel grid = slotGrid(items.size());
		for (int i = 0; i < gridSlots(items.size()); i++)
		{
			if (i < items.size())
			{
				PanelModel.LootView item = items.get(i);
				grid.add(slot(item.itemId, item.quantity, lootTooltip(item), SLOT, item.excluded,
					() -> actions.accept(Action.TOGGLE_LOOT, sourceKey + "\n" + item.itemId)));
			}
			else
			{
				grid.add(emptySlot(SLOT));
			}
		}
		return grid;
	}

	private JPanel supplyGrid(String sourceKey, List<PanelModel.SupplyView> supplies)
	{
		JPanel grid = slotGrid(supplies.size());
		for (int i = 0; i < gridSlots(supplies.size()); i++)
		{
			if (i < supplies.size())
			{
				PanelModel.SupplyView supply = supplies.get(i);
				grid.add(slot(supply.itemId, supply.quantity, supplyTooltip(supply), SUPPLY_SLOT, supply.excluded,
					() -> actions.accept(Action.TOGGLE_SUPPLY, sourceKey + "\n" + supply.lineKey)));
			}
			else
			{
				grid.add(emptySlot(SUPPLY_SLOT));
			}
		}
		return grid;
	}

	private static int gridSlots(int items)
	{
		return Math.max(1, (items + ICON_COLUMNS - 1) / ICON_COLUMNS) * ICON_COLUMNS;
	}

	private static JPanel slotGrid(int items)
	{
		JPanel grid = new JPanel(new GridLayout(gridSlots(items) / ICON_COLUMNS, ICON_COLUMNS, 1, 1));
		grid.setBackground(ColorScheme.DARK_GRAY_COLOR);
		grid.setAlignmentX(LEFT_ALIGNMENT);
		return grid;
	}

	/**
	 * One item slot. Right-click toggles whether the item counts towards profit;
	 * excluded items are drawn faded, like ignored items in the Loot Tracker.
	 */
	private JPanel slot(int itemId, long quantity, String tooltip, Color background, boolean excluded, Runnable toggle)
	{
		JPanel slot = emptySlot(background);
		JLabel icon = new JLabel();
		icon.setHorizontalAlignment(SwingConstants.CENTER);
		icon.setVerticalAlignment(SwingConstants.CENTER);
		icon.setToolTipText(excluded ? tooltip.replace("</html>", "<br><i>Excluded from profit</i></html>") : tooltip);
		int qty = (int) Math.min(Integer.MAX_VALUE, quantity);
		AsyncBufferedImage image = itemManager.getImage(itemId, qty, qty > 1);
		if (excluded)
		{
			image.onLoaded(() -> SwingUtilities.invokeLater(() ->
				icon.setIcon(new ImageIcon(ImageUtil.alphaOffset(image, 0.3f)))));
		}
		else
		{
			image.addTo(icon);
		}
		slot.add(icon);

		JPopupMenu menu = new JPopupMenu();
		JMenuItem item = new JMenuItem(excluded ? "Include in profit" : "Exclude from profit");
		item.addActionListener(e -> toggle.run());
		menu.add(item);
		slot.setComponentPopupMenu(menu);
		icon.setInheritsPopupMenu(true);
		return slot;
	}

	private static JPanel emptySlot(Color background)
	{
		JPanel slot = new JPanel();
		slot.setBackground(background);
		slot.setPreferredSize(new Dimension(36, 34));
		return slot;
	}

	/** Small rounded-looking tags, one per skill, wrapped to the panel width. */
	private static JPanel xpBubbles(Map<String, Long> xpBySkill)
	{
		JPanel rows = new JPanel();
		rows.setLayout(new BoxLayout(rows, BoxLayout.Y_AXIS));
		rows.setAlignmentX(LEFT_ALIGNMENT);
		JPanel current = null;
		int used = 0;
		for (Map.Entry<String, Long> entry : xpBySkill.entrySet())
		{
			JLabel bubble = new JLabel("<html>" + entry.getKey() + " <font color='#ffffff'>"
				+ QuantityFormatter.formatNumber(entry.getValue()) + "</font></html>");
			bubble.setFont(FontManager.getRunescapeSmallFont());
			bubble.setForeground(ColorScheme.TEXT_COLOR);
			bubble.setOpaque(true);
			bubble.setBackground(BUBBLE);
			bubble.setBorder(new EmptyBorder(2, 7, 2, 7));
			FontMetrics fm = bubble.getFontMetrics(bubble.getFont());
			int width = fm.stringWidth(entry.getKey() + " " + QuantityFormatter.formatNumber(entry.getValue())) + 18;
			if (current == null || used + width > CONTENT_WIDTH)
			{
				current = new JPanel(new FlowLayout(FlowLayout.LEFT, 0, 0));
				current.setAlignmentX(LEFT_ALIGNMENT);
				current.setBorder(new EmptyBorder(0, 0, 3, 0));
				rows.add(current);
				used = 0;
			}
			if (used > 0)
			{
				current.add(Box.createHorizontalStrut(4));
			}
			current.add(bubble);
			used += width + 4;
		}
		return rows;
	}

	// ---------------------------------------------------------------- tooltips

	private static String lootTooltip(PanelModel.LootView item)
	{
		StringBuilder sb = new StringBuilder("<html>");
		sb.append(item.name).append(" x ").append(QuantityFormatter.formatNumber(item.quantity));
		if (item.itemId == ItemID.COINS)
		{
			return sb.append("</html>").toString();
		}
		if (item.tradeable)
		{
			sb.append("<br>GE: ").append(QuantityFormatter.quantityToStackSize(item.geTotal()));
			if (item.quantity > 1)
			{
				sb.append(" (").append(QuantityFormatter.quantityToStackSize(item.geEach)).append(" ea)");
			}
		}
		else
		{
			sb.append("<br>Untradeable, valued at High Alchemy");
		}
		sb.append("<br>HA: ").append(QuantityFormatter.quantityToStackSize(item.haTotal()));
		if (item.quantity > 1)
		{
			sb.append(" (").append(QuantityFormatter.quantityToStackSize(item.haEach)).append(" ea)");
		}
		return sb.append("</html>").toString();
	}

	private static String supplyTooltip(PanelModel.SupplyView supply)
	{
		String unit = supply.unit == null ? "" : " " + supply.unit;
		StringBuilder sb = new StringBuilder("<html>");
		sb.append(supply.name).append(" x ").append(QuantityFormatter.formatNumber(supply.quantity)).append(unit);
		sb.append("<br>Cost: ").append(QuantityFormatter.quantityToStackSize(supply.gp));
		if (supply.quantity > 1)
		{
			sb.append(" (").append(QuantityFormatter.quantityToStackSize(supply.gp / supply.quantity))
				.append(supply.unit == null ? " ea" : " per " + supply.unit.replaceAll("s$", "")).append(")");
		}
		return sb.append("</html>").toString();
	}

	// ---------------------------------------------------------------- helpers

	/**
	 * Toggles on mouse press rather than click: the panel redraws every tick while
	 * you're active, which would lose a click whose press and release straddle a redraw.
	 */
	private static void onPress(JPanel target, Runnable action, Color background)
	{
		target.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mousePressed(MouseEvent e)
			{
				if (e.getButton() == MouseEvent.BUTTON1)
				{
					action.run();
				}
			}

			@Override
			public void mouseEntered(MouseEvent e)
			{
				target.setBackground(ColorScheme.DARKER_GRAY_HOVER_COLOR);
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				target.setBackground(background);
			}
		});
	}

	private static JPanel indented(JPanel box)
	{
		JPanel wrap = new JPanel(new BorderLayout());
		wrap.setBorder(new EmptyBorder(0, 6, 0, 0));
		wrap.setAlignmentX(LEFT_ALIGNMENT);
		wrap.add(box, BorderLayout.CENTER);
		return wrap;
	}

	private static JPanel row()
	{
		JPanel row = new JPanel(new BorderLayout());
		row.setOpaque(false);
		row.setAlignmentX(LEFT_ALIGNMENT);
		return row;
	}

	private static String html(String label, String value, String valueColor)
	{
		return "<html><font color='#a5a5a5'>" + label + "</font> <font color='" + valueColor + "'>" + value + "</font></html>";
	}

	private static String gp(long value)
	{
		return QuantityFormatter.quantityToStackSize(value) + " gp";
	}

	private static void setProfit(JLabel label, long profit)
	{
		label.setText((profit > 0 ? "+" : "") + QuantityFormatter.quantityToStackSize(profit));
		label.setForeground(profit >= 0 ? PROFIT_COLOR : LOSS_COLOR);
	}

	private static JLabel small(String text, Color color)
	{
		JLabel label = new JLabel(text);
		label.setFont(FontManager.getRunescapeSmallFont());
		label.setForeground(color);
		return label;
	}

	private static JLabel note(String text)
	{
		JLabel label = new JLabel("<html>" + text + "</html>");
		label.setFont(FontManager.getRunescapeSmallFont());
		label.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		label.setBorder(new EmptyBorder(8, 2, 8, 2));
		label.setAlignmentX(LEFT_ALIGNMENT);
		return label;
	}
}

package com.gildedledger.ui;

/**
 * Per-item prices for loot. The value used for profit is the Grand Exchange
 * price, or the High Alchemy price when the item can't be traded.
 */
public interface LootPrices
{
	long ge(int itemId);

	long highAlch(int itemId);

	boolean tradeable(int itemId);

	/** GE price for tradeable items with a price; High Alchemy price otherwise. */
	default long value(int itemId)
	{
		long ge = ge(itemId);
		return tradeable(itemId) && ge > 0 ? ge : highAlch(itemId);
	}
}

package com.gildedledger.ui;

import com.gildedledger.data.SourceCategory;
import com.gildedledger.data.SourceRecord;
import com.gildedledger.data.SupplyLine;
import com.gildedledger.data.TaskRecord;
import com.gildedledger.data.TrackerData;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.EnumMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.function.IntFunction;

/**
 * An immutable snapshot of the ledger with prices already applied. Built on the
 * client thread (where item lookups are allowed) and handed to Swing to draw.
 */
public final class PanelModel
{
	/** Skills in the order RuneLite's skill panel lists combat stats, then everything else. */
	private static final List<String> SKILL_ORDER = List.of(
		"Attack", "Strength", "Defence", "Ranged", "Magic", "Hitpoints", "Prayer", "Slayer",
		"Farming", "Woodcutting");

	public static final class LootView
	{
		public final int itemId;
		public final String name;
		public final long quantity;
		public final long geEach;
		public final long haEach;
		public final boolean tradeable;
		/** GE total, or HA total when untradeable. */
		public final long value;
		/** The player excluded this item from profit; shown greyed out. */
		public final boolean excluded;

		LootView(int itemId, String name, long quantity, LootPrices prices, boolean excluded)
		{
			this.excluded = excluded;
			this.itemId = itemId;
			this.name = name;
			this.quantity = quantity;
			this.geEach = prices.ge(itemId);
			this.haEach = prices.highAlch(itemId);
			this.tradeable = prices.tradeable(itemId);
			this.value = prices.value(itemId) * quantity;
		}

		public long geTotal()
		{
			return geEach * quantity;
		}

		public long haTotal()
		{
			return haEach * quantity;
		}
	}

	public static final class SupplyView
	{
		public final String lineKey;
		public final boolean excluded;
		public final int itemId;
		public final String name;
		public final long quantity;
		public final long gp;
		public final String unit;

		SupplyView(String lineKey, SupplyLine line, boolean excluded)
		{
			this.lineKey = lineKey;
			this.excluded = excluded;
			this.itemId = line.itemId;
			this.name = line.name;
			this.quantity = line.quantity;
			this.gp = line.gp;
			this.unit = line.unit;
		}
	}

	public static final class SourceView
	{
		public final String key;
		public final String name;
		public final SourceCategory category;
		public final long count;
		public final long lootValue;
		public final long lootHa;
		public final long supplyGp;
		public final long xp;
		/** Skill name → XP, in skill-panel order. */
		public final Map<String, Long> xpBySkill;
		public final List<LootView> loot;
		public final List<SupplyView> supplies;
		public final long lastUpdatedMillis;

		SourceView(SourceRecord r, List<LootView> loot, List<SupplyView> supplies)
		{
			this.key = r.key;
			this.name = r.name;
			this.category = r.category;
			this.count = r.count;
			long value = 0;
			long ha = 0;
			for (LootView item : loot)
			{
				if (!item.excluded)
				{
					value += item.value;
					ha += item.haTotal();
				}
			}
			this.lootValue = value;
			this.lootHa = ha;
			this.supplyGp = r.supplyCost();
			this.xp = r.totalXp();
			this.xpBySkill = orderedXp(r.xp);
			this.loot = loot;
			this.supplies = supplies;
			this.lastUpdatedMillis = r.lastUpdatedMillis;
		}

		public long profit()
		{
			return lootValue - supplyGp;
		}
	}

	public static final class TaskView
	{
		public final String name;
		public final String location;
		public final int remaining;
		public final int initial;
		public final long kills;
		public final long lootGp;
		public final long supplyGp;
		public final long xp;
		public final long slayerXp;
		public final boolean finished;

		TaskView(TaskRecord t)
		{
			this.name = t.taskName;
			this.location = t.location;
			this.remaining = t.remainingAmount;
			this.initial = t.initialAmount;
			this.kills = t.kills;
			this.lootGp = t.lootGp;
			this.supplyGp = t.supplyGp;
			this.xp = t.xp;
			this.slayerXp = t.slayerXp;
			this.finished = t.isFinished();
		}

		public long profit()
		{
			return lootGp - supplyGp;
		}
	}

	public final boolean ready;
	public final TaskView task;
	public final List<SourceView> sources;

	private PanelModel(boolean ready, TaskView task, List<SourceView> sources)
	{
		this.ready = ready;
		this.task = task;
		this.sources = sources;
	}

	public static PanelModel build(TrackerData data, LootPrices prices, IntFunction<String> itemName, boolean ready)
	{
		return build(data, prices, itemName, ready, false);
	}

	/**
	 * @param combineSkills show each skill as one combined table instead of one entry
	 *                      per item; PvM always keeps one entry per monster
	 */
	public static PanelModel build(TrackerData data, LootPrices prices, IntFunction<String> itemName, boolean ready,
		boolean combineSkills)
	{
		List<SourceView> views = new ArrayList<>();
		for (SourceRecord record : displayRecords(data, combineSkills))
		{
			List<LootView> loot = new ArrayList<>();
			for (Map.Entry<Integer, Long> e : record.loot.entrySet())
			{
				loot.add(new LootView(e.getKey(), itemName.apply(e.getKey()), e.getValue(), prices,
					record.excludedLoot.contains(e.getKey())));
			}
			loot.sort(Comparator.comparingLong((LootView v) -> v.value).reversed());

			List<SupplyView> supplies = new ArrayList<>();
			for (Map.Entry<String, SupplyLine> line : record.supplies.entrySet())
			{
				supplies.add(new SupplyView(line.getKey(), line.getValue(), record.excludedSupplies.contains(line.getKey())));
			}
			supplies.sort(Comparator.comparingLong((SupplyView v) -> v.gp).reversed());

			views.add(new SourceView(record, Collections.unmodifiableList(loot), Collections.unmodifiableList(supplies)));
		}
		TaskView task = data.currentTask == null ? null : new TaskView(data.currentTask);
		return new PanelModel(ready, task, Collections.unmodifiableList(views));
	}

	/** The saved records, or with skills merged into one record per category for display. */
	private static List<SourceRecord> displayRecords(TrackerData data, boolean combineSkills)
	{
		List<SourceRecord> records = new ArrayList<>();
		Map<SourceCategory, SourceRecord> combined = new EnumMap<>(SourceCategory.class);
		for (SourceRecord record : data.sources.values())
		{
			if (record.isEmpty())
			{
				continue;
			}
			if (!combineSkills || record.category == SourceCategory.COMBAT)
			{
				records.add(record);
				continue;
			}
			SourceRecord table = combined.get(record.category);
			if (table == null)
			{
				table = new SourceRecord(COMBINED_PREFIX + record.category.name(), record.category.getLabel(),
					record.category, Long.MAX_VALUE);
				table.lastUpdatedMillis = 0;
				combined.put(record.category, table);
				records.add(table);
			}
			table.mergeFrom(copyOf(record));
		}
		return records;
	}

	/** A deep copy, so merging for display never changes the saved records. */
	private static SourceRecord copyOf(SourceRecord r)
	{
		SourceRecord copy = new SourceRecord(r.key, r.name, r.category, r.firstSeenMillis);
		copy.count = r.count;
		copy.lastUpdatedMillis = r.lastUpdatedMillis;
		copy.loot.putAll(r.loot);
		copy.xp.putAll(r.xp);
		copy.excludedLoot.addAll(r.excludedLoot);
		copy.excludedSupplies.addAll(r.excludedSupplies);
		r.supplies.forEach((key, line) ->
		{
			SupplyLine dup = new SupplyLine(line.itemId, line.name, line.unit);
			dup.quantity = line.quantity;
			dup.gp = line.gp;
			copy.supplies.put(key, dup);
		});
		return copy;
	}

	/** Key prefix of a skill shown as one combined table. */
	public static final String COMBINED_PREFIX = "category:";

	public static Map<String, Long> orderedXp(Map<String, Long> xp)
	{
		Map<String, Long> ordered = new LinkedHashMap<>();
		for (String skill : SKILL_ORDER)
		{
			Long amount = xp.get(skill);
			if (amount != null && amount > 0)
			{
				ordered.put(skill, amount);
			}
		}
		xp.forEach((skill, amount) ->
		{
			if (!ordered.containsKey(skill) && amount != null && amount > 0)
			{
				ordered.put(skill, amount);
			}
		});
		return Collections.unmodifiableMap(ordered);
	}
}

package com.gildedledger;

import com.gildedledger.tracking.ItemInfo;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;

/** In-memory item table for tests. */
public class FakeItems implements ItemInfo
{
	private final Map<Integer, String> names = new HashMap<>();
	private final Map<Integer, Long> prices = new HashMap<>();
	private final Set<Integer> stackable = new HashSet<>();
	private final Map<Integer, Integer> noted = new HashMap<>();

	public FakeItems add(int id, String name, long price)
	{
		names.put(id, name);
		prices.put(id, price);
		return this;
	}

	public FakeItems stackable(int id, String name, long price)
	{
		add(id, name, price);
		stackable.add(id);
		return this;
	}

	public FakeItems noted(int notedId, int baseId)
	{
		noted.put(notedId, baseId);
		stackable.add(notedId);
		names.put(notedId, names.get(baseId));
		return this;
	}

	@Override
	public String name(int itemId)
	{
		return names.getOrDefault(itemId, "");
	}

	@Override
	public long marketPrice(int itemId)
	{
		return prices.getOrDefault(canonical(itemId), 0L);
	}

	@Override
	public boolean stackable(int itemId)
	{
		return stackable.contains(itemId);
	}

	@Override
	public int canonical(int itemId)
	{
		return noted.getOrDefault(itemId, itemId);
	}
}

package com.gildedledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import com.gildedledger.data.SourceRecord;
import com.gildedledger.tracking.FarmingTracker;
import com.gildedledger.tracking.InventoryDiff;
import com.gildedledger.tracking.Ledger;
import com.gildedledger.tracking.TileKey;
import java.util.HashMap;
import java.util.Map;
import org.junit.Before;
import org.junit.Test;

public class FarmingTrackerTest
{
	private static final int RANARR_SEED = 5295;
	private static final int SNAPDRAGON_SEED = 5300;
	private static final int GRIMY_RANARR = 207;
	private static final int GRIMY_RANARR_NOTED = 208;
	private static final int ULTRACOMPOST = 21483;
	private static final int BUCKET = 1925;
	private static final int MAGIC_SAPLING = 5316;
	private static final int COCONUT = 5974;
	private static final int MAGIC_LOGS = 1513;

	private static final TileKey HERB_PATCH = new TileKey(2813, 3463, 0);
	private static final TileKey TREE_PATCH = new TileKey(3228, 3459, 0);

	private Ledger ledger;
	private FarmingTracker farming;

	@Before
	public void setUp()
	{
		FakeItems items = new FakeItems()
			.add(RANARR_SEED, "Ranarr seed", 40_000)
			.add(SNAPDRAGON_SEED, "Snapdragon seed", 60_000)
			.add(GRIMY_RANARR, "Grimy ranarr weed", 7_000)
			.noted(GRIMY_RANARR_NOTED, GRIMY_RANARR)
			.add(ULTRACOMPOST, "Ultracompost", 1_000)
			.add(BUCKET, "Bucket", 5)
			.add(MAGIC_SAPLING, "Magic sapling", 100_000)
			.add(COCONUT, "Coconut", 900)
			.add(MAGIC_LOGS, "Magic logs", 1_100);
		ledger = new Ledger(() -> 1_000L);
		Map<String, Integer> compost = new HashMap<>();
		compost.put("Ultracompost", ULTRACOMPOST);
		farming = new FarmingTracker(ledger, items, compost);
	}

	private static InventoryDiff change(int... idAndDelta)
	{
		Map<Integer, Integer> before = new HashMap<>();
		Map<Integer, Integer> after = new HashMap<>();
		for (int i = 0; i < idAndDelta.length; i += 2)
		{
			before.put(idAndDelta[i], 100);
			after.put(idAndDelta[i], 100 + idAndDelta[i + 1]);
		}
		return InventoryDiff.between(before, after);
	}

	private SourceRecord source(String key)
	{
		return ledger.data().sources.get(key);
	}

	@Test
	public void herbRunBooksHarvestToOldCropAndCostsToNewCrop()
	{
		ledger.data().patchCrops.put(HERB_PATCH.pack(), "Ranarr");

		farming.onPatchClicked(HERB_PATCH, "Herb", null, 1);
		farming.onInventoryChanged(change(GRIMY_RANARR, 3));
		farming.onXp("Farming", 82);
		farming.onGameTick(2, HERB_PATCH);
		farming.onInventoryChanged(change(GRIMY_RANARR, 2));
		farming.onXp("Farming", 55);
		farming.onGameTick(3, HERB_PATCH);

		// Compost first, then plant something new.
		farming.onPatchClicked(HERB_PATCH, "Herb", null, 5);
		farming.onInventoryChanged(change(ULTRACOMPOST, -1, BUCKET, 1));
		farming.onChatMessage("You treat the herb patch with ultracompost.");
		farming.onXp("Farming", 36);
		farming.onGameTick(5, HERB_PATCH);
		farming.onPatchClicked(HERB_PATCH, "Herb", null, 6);
		farming.onInventoryChanged(change(SNAPDRAGON_SEED, -1));
		farming.onXp("Farming", 87);
		farming.onGameTick(6, HERB_PATCH);

		SourceRecord ranarr = source("farming:Herb:Ranarr");
		assertEquals(5L, (long) ranarr.loot.get(GRIMY_RANARR));
		assertFalse(ranarr.loot.containsKey(BUCKET));
		assertEquals(1, ranarr.count);
		assertEquals(0, ranarr.supplyCost());

		SourceRecord snapdragon = source("farming:Herb:Snapdragon");
		assertEquals("Herb: Snapdragon", snapdragon.name);
		assertEquals(61_000, snapdragon.supplyCost());
		assertEquals(0, snapdragon.count);
		assertEquals(87L, (long) snapdragon.xp.get("Farming"));
		assertEquals("Snapdragon", ledger.data().patchCrops.get(HERB_PATCH.pack()));
	}

	@Test
	public void notingHerbsAtTheLeprechaunIsNotLoot()
	{
		ledger.data().patchCrops.put(HERB_PATCH.pack(), "Ranarr");
		farming.onPatchClicked(HERB_PATCH, "Herb", null, 1);
		farming.onInventoryChanged(change(GRIMY_RANARR, 6));
		farming.onGameTick(2, HERB_PATCH);

		farming.onOtherAction();
		farming.onInventoryChanged(change(GRIMY_RANARR, -6, GRIMY_RANARR_NOTED, 6));
		farming.onGameTick(3, HERB_PATCH);

		SourceRecord ranarr = source("farming:Herb:Ranarr");
		assertEquals(1, ranarr.loot.size());
		assertEquals(6L, (long) ranarr.loot.get(GRIMY_RANARR));
	}

	@Test
	public void noteConversionsAreNotChanges()
	{
		FakeItems items = new FakeItems().add(GRIMY_RANARR, "Grimy ranarr weed", 7_000).noted(GRIMY_RANARR_NOTED, GRIMY_RANARR);
		InventoryDiff noting = change(GRIMY_RANARR, -6, GRIMY_RANARR_NOTED, 6).withoutNoteConversions(items);
		assertTrue(noting.isEmpty());

		InventoryDiff partly = change(GRIMY_RANARR, -6, GRIMY_RANARR_NOTED, 4).withoutNoteConversions(items);
		assertEquals(-2, partly.change(GRIMY_RANARR));
		assertEquals(0, partly.change(GRIMY_RANARR_NOTED));
		assertTrue(partly.hasNoGains());
	}

	@Test
	public void bottomlessBucketCompostIsCharged()
	{
		farming.onPatchClicked(HERB_PATCH, "Herb", null, 1);
		farming.onChatMessage("You treat the herb patch with ultracompost.");
		farming.onGameTick(1, HERB_PATCH);
		farming.onInventoryChanged(change(RANARR_SEED, -1));
		farming.onGameTick(2, HERB_PATCH);

		assertEquals(41_000, source("farming:Herb:Ranarr").supplyCost());
	}

	@Test
	public void treeRunTracksSaplingPaymentCheckHealthAndLogs()
	{
		// Plant and pay the gardener.
		farming.onPatchClicked(TREE_PATCH, "Tree", null, 1);
		farming.onInventoryChanged(change(MAGIC_SAPLING, -1));
		farming.onXp("Farming", 145);
		farming.onGameTick(2, TREE_PATCH);
		farming.onOtherAction();
		farming.onGardenerPayment(change(COCONUT, -25), 10, new TileKey(3230, 3460, 0));
		farming.onGameTick(10, TREE_PATCH);

		SourceRecord magic = source("farming:Tree:Magic");
		assertEquals("Tree: Magic", magic.name);
		assertEquals(100_000 + 25 * 900, magic.supplyCost());
		assertEquals(0, magic.count);

		// Days later: check health and chop it down.
		farming.onPatchClicked(TREE_PATCH, "Tree", "Magic tree", 5000);
		farming.onXp("Farming", 13_913);
		farming.onGameTick(5001, TREE_PATCH);
		farming.onPatchClicked(TREE_PATCH, "Tree", "Magic tree", 5002);
		farming.onInventoryChanged(change(MAGIC_LOGS, 1));
		farming.onXp("Woodcutting", 250);
		farming.onGameTick(5005, TREE_PATCH);

		assertEquals(1, magic.count);
		assertEquals(13_913L + 145, (long) magic.xp.get("Farming"));
		assertEquals(250L, (long) magic.xp.get("Woodcutting"));
		assertEquals(1L, (long) magic.loot.get(MAGIC_LOGS));
	}

	@Test
	public void unknownCropFallsBackToPatchAppearanceOrUnknown()
	{
		farming.onPatchClicked(TREE_PATCH, "Tree", "Yew", 1);
		farming.onXp("Farming", 7_000);
		farming.onGameTick(2, TREE_PATCH);
		assertEquals(1, source("farming:Tree:Yew").count);

		farming.onPatchClicked(HERB_PATCH, "Herb", null, 3);
		farming.onInventoryChanged(change(GRIMY_RANARR, 4));
		farming.onGameTick(4, HERB_PATCH);
		assertEquals("Herb patch (unknown crop)", source("farming:Herb:Unknown").name);
	}

	@Test
	public void walkingAwayEndsTheSession()
	{
		ledger.data().patchCrops.put(HERB_PATCH.pack(), "Ranarr");
		farming.onPatchClicked(HERB_PATCH, "Herb", null, 1);
		farming.onGameTick(2, new TileKey(2900, 3500, 0));

		farming.onInventoryChanged(change(GRIMY_RANARR, 4));
		farming.onGameTick(3, new TileKey(2900, 3500, 0));
		assertNull(source("farming:Herb:Ranarr"));
	}
}

